@Override
	public void tick() {
		BroodEetle broodEetle = this.broodEetle;
		if (broodEetle.isFiringCannon()) {
			this.cannonTicks++;

			if (broodEetle.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_SLAM)) {
				if (broodEetle.getAnimationTick() == 14) {
					BroodEetleSlamGoal.slam(broodEetle, broodEetle.getRandom(), 1.25F);
				}
			} else if (broodEetle.isEggMouthOpen() && this.cannonTicks % 20 == 0) {
				RandomSource random = broodEetle.getRandom();
				if (BroodEetleLaunchEggsGoal.getNearbyEetleCount(broodEetle) <= 9 || this.cannonTicks <= 75 || random.nextFloat() <= 0.05F) {
					NetworkUtil.setPlayingAnimation(broodEetle, EEPlayableEndimations.BROOD_EETLE_LAUNCH);
					Vec3 firingPos = new Vec3(-1.0D, 3.0D, 0.0D).yRot(-broodEetle.yBodyRot * ((float) Math.PI / 180F) - ((float) Math.PI / 2F));
					EetleEgg eetleEgg = new EetleEgg(broodEetle.level(), broodEetle.position().add(firingPos));
					eetleEgg.setEggSize(EetleEgg.EggSize.random(random, false));
					eetleEgg.setDeltaMovement(new Vec3((random.nextFloat() - random.nextFloat()) * 0.35F, 0.8F + random.nextFloat() * 0.1F, (random.nextFloat() - random.nextFloat()) * 0.35F));
					broodEetle.level().addFreshEntity(eetleEgg);
				} else {
					broodEetle.heal(5.0F);
					broodEetle.level().broadcastEntityEvent(broodEetle, (byte) 60);
				}
			}
		}
	}

@Override
	public boolean canUse() {
		BroodEetle broodEetle = this.broodEetle;
		return broodEetle.isOnLastHealthStage() && broodEetle.isAlive() && !broodEetle.isFlying();
	}

@Override
	public void start() {
		BroodEetle broodEetle = this.broodEetle;
		broodEetle.getNavigation().stop();
		NetworkUtil.setPlayingAnimation(broodEetle, EEPlayableEndimations.BROOD_EETLE_SLAM);
		broodEetle.setFiringCannon(true);
	}

@Override
	public void stop() {
		BroodEetle broodEetle = this.broodEetle;
		broodEetle.setFiringCannon(false);
	}

@Override
	public boolean canContinueToUse() {
		BroodEetle broodEetle = this.broodEetle;
		return broodEetle.isAlive() && broodEetle.isOnLastHealthStage();
	}

@Override
	public boolean requiresUpdateEveryTick() {
		return true;
	}

@Override
	protected void registerGoals() {
		this.goalSelector.addGoal(0, new BroodEetleLastStageGoal(this));
		this.goalSelector.addGoal(0, new BroodEetleSleepGoal(this));
		this.goalSelector.addGoal(1, new BroodEetleDropEggsGoal(this));
		this.goalSelector.addGoal(1, new BroodEetleAirSlamGoal(this));
		this.goalSelector.addGoal(2, new BroodEetleLandGoal(this));
		this.goalSelector.addGoal(3, new BroodEetleFlyNearPosGoal(this));
		this.goalSelector.addGoal(3, new BroodEetleLaunchEggsGoal(this));
		this.goalSelector.addGoal(4, new BroodEetleTakeoffGoal(this));
		this.goalSelector.addGoal(5, new BroodEetleSlamGoal(this));
		this.goalSelector.addGoal(6, new BroodEetleFlingGoal(this));
		this.goalSelector.addGoal(7, new RandomLookAroundGoal(this));
		this.goalSelector.addGoal(8, new LookAtPlayerGoal(this, AbstractEetle.class, 8.0F));
		this.targetSelector.addGoal(1, new BroodEetleHurtByTargetGoal(this));
	}

public boolean isOnLastHealthStage() {
		return this.getHealthStage() == HealthStage.FIVE;
	}

public boolean isEggMouthOpen() {
		return this.eggMouthEndimation.isMaxed();
	}

public boolean isFiringCannon() {
		return this.entityData.get(FIRING_CANNON);
	}

public void setFiringCannon(boolean firingCannon) {
		this.entityData.set(FIRING_CANNON, firingCannon);
	}

@Override
	public void handleEntityEvent(byte id) {
		if (id == 60) {
			this.healPulseEndimation.setDecrementing(false);
		} else {
			super.handleEntityEvent(id);
		}
	}

public static int getNearbyEetleCount(BroodEetle broodEetle) {
		double followRange = broodEetle.getAttributeValue(Attributes.FOLLOW_RANGE);
		double posY = broodEetle.getY();
		Sensing senses = broodEetle.getSensing();
		return broodEetle.level().getEntitiesOfClass(AbstractEetle.class, broodEetle.getBoundingBox().inflate(followRange, followRange * 0.75D, followRange), eetle -> {
			if (eetle.getY() - posY >= 0.5F && !senses.hasLineOfSight(eetle)) {
				return false;
			}
			return eetle.isAlive() && (!eetle.isBaby() || eetle.getGrowingAge() >= -240);
		}).size();
	}

public static void slam(BroodEetle broodEetle, RandomSource random, float power) {
		ServerLevel world = (ServerLevel) broodEetle.level();
		double posX = broodEetle.getX();
		double posY = broodEetle.getY();
		double posZ = broodEetle.getZ();
		for (BlockState state : sampleGround(world, broodEetle.blockPosition().below(), random)) {
			world.sendParticles(new BlockParticleOption(EEParticleTypes.FAST_BLOCK.get(), state), posX, posY, posZ, 8, 0.0D, 0.0D, 0.0D, 0.225F);
		}
		float attackDamage = (float) broodEetle.getAttributeValue(Attributes.ATTACK_DAMAGE) * power;
		double knockback = broodEetle.getAttributeValue(Attributes.ATTACK_KNOCKBACK);
		for (LivingEntity livingEntity : world.getEntitiesOfClass(LivingEntity.class, broodEetle.getBoundingBox().inflate(4.5D), entity1 -> entity1 != broodEetle)) {
			float damage;
			if ((int) attackDamage > 0.0F) {
				damage = attackDamage / 2.0F + random.nextInt((int) attackDamage);
			} else {
				damage = attackDamage;
			}

			if (livingEntity instanceof AbstractEetle) {
				damage = 0.0F;
			}

			if (livingEntity.hurt(world.damageSources().mobAttack(broodEetle), damage)) {
				broodEetle.doEnchantDamageEffects(broodEetle, livingEntity);
				double knockbackForce = knockback - livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
				float inAirFactor = livingEntity.onGround() ? 1.0F : 0.75F;
				Vec3 horizontalVelocity = new Vec3(livingEntity.getX() - posX, 0.0D, livingEntity.getZ() - posZ).normalize().scale((knockbackForce * (random.nextFloat() * 0.75F + 0.5F)) * inAirFactor * power);
				livingEntity.push(horizontalVelocity.x, knockbackForce * 0.5F * random.nextFloat() * 0.5F * inAirFactor, horizontalVelocity.z);
				livingEntity.hurtMarked = true;
			}
		}
	}

@Override
	public void tick() {
		this.xo = this.getX();
		this.yo = this.getY();
		this.zo = this.getZ();
		this.fallTime++;
		if (!this.isNoGravity()) {
			this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.04D, 0.0D));
		}

		this.move(MoverType.SELF, this.getDeltaMovement());

		Level world = this.level();
		if (!world.isClientSide) {
			BlockPos newPos = this.blockPosition();
			if (!this.onGround() && !world.getFluidState(newPos).is(FluidTags.WATER)) {
				if (this.fallTime > 100 && (newPos.getY() < 1 || newPos.getY() > 256) || this.fallTime > 600) {
					burstOpenEgg(world, newPos, this.random, this.eggSize.ordinal(), this.fromBroodEetle);
				}
			} else {
				BlockState state = world.getBlockState(newPos);
				this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.5D, 0.7D));
				this.discard();
				boolean flag3 = FallingBlock.isFree(world.getBlockState(newPos.below()));
				BlockState placingState = EETLE_EGGS_BLOCK.defaultBlockState().setValue(EetleEggBlock.SIZE, this.eggSize.ordinal());
				boolean flag4 = placingState.canSurvive(world, newPos) && !flag3;
				RandomSource random = this.random;
				if (state.canBeReplaced(new DirectionalPlaceContext(world, newPos, Direction.DOWN, ItemStack.EMPTY, Direction.UP)) && flag4) {
					if (placingState.hasProperty(BlockStateProperties.WATERLOGGED) && world.getFluidState(newPos).getType() == Fluids.WATER) {
						placingState = placingState.setValue(BlockStateProperties.WATERLOGGED, true);
					}

					placingState = assignRandomDirection(world, placingState, random, newPos);
					if (world.setBlock(newPos, placingState, 3)) {
						world.playSound(null, newPos, EESoundEvents.EETLE_EGG_PLACE.get(), SoundSource.BLOCKS, 1.0F - random.nextFloat() * 0.1F, 0.8F + random.nextFloat() * 0.2F);
						if (!placingState.getValue(BlockStateProperties.WATERLOGGED)) {
							BlockEntity tileentity = world.getBlockEntity(newPos);
							if (tileentity instanceof EetleEggTileEntity) {
								EetleEggTileEntity eetleEggsTileEntity = (EetleEggTileEntity) tileentity;
								eetleEggsTileEntity.fromBroodEetle = this.fromBroodEetle;
								eetleEggsTileEntity.updateHatchDelay(world, random.nextInt(6) + 5);
								eetleEggsTileEntity.bypassSpawningGameRule();
							}
						}
					}
				} else {
					burstOpenEgg(world, newPos, random, this.eggSize.ordinal(), this.fromBroodEetle);
				}
			}
		} else {
			for (EetleEggTileEntity.SackGrowth growth : this.sackGrowths) {
				growth.tick();
			}
		}

		this.setDeltaMovement(this.getDeltaMovement().scale(0.98D));
	}

private static void burstOpenEgg(Level world, BlockPos pos, RandomSource random, int size, boolean fromBroodEetle) {
		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();
		for (int i = 0; i <= size; i++) {
			AbstractEetle eetle = random.nextFloat() < 0.6F ? EEEntityTypes.CHARGER_EETLE.get().create(world) : EEEntityTypes.GLIDER_EETLE.get().create(world);
			if (eetle != null) {
				eetle.markFromEgg();
				eetle.updateAge(-(random.nextInt(41) + 120));
				eetle.absMoveTo(x + random.nextFloat(), y + 0.1F, z + random.nextFloat(), random.nextFloat() * 360.0F, 0.0F);
				if (fromBroodEetle) {
					eetle.applyDespawnTimer();
				}
				world.addFreshEntity(eetle);
			}
		}
		if (world instanceof ServerLevel) {
			world.playSound(null, pos, EESoundEvents.EETLE_EGG_BREAK.get(), SoundSource.BLOCKS, 1.0F - random.nextFloat() * 0.1F, 0.8F + random.nextFloat() * 0.2F);
			((ServerLevel) world).sendParticles(CorrockCrownParticleData.EETLE, x + 0.5F, y + 0.25F * (size + 1.0F), z + 0.5F, 5 + size, 0.3F, 0.1F, 0.3F, 0.1D);
		}
	}

private static BlockState assignRandomDirection(Level world, BlockState state, RandomSource random, BlockPos pos) {
		EetleEggBlock.shuffleDirections(DIRECTIONS, random);
		for (Direction direction : DIRECTIONS) {
			BlockState directionState = state.setValue(EetleEggBlock.FACING, direction);
			if (directionState.canSurvive(world, pos)) {
				return directionState;
			}
		}
		return state;
	}

@Override
	protected void addAdditionalSaveData(CompoundTag compound) {
		compound.putInt("FallTime", this.fallTime);
		compound.putInt("EggSize", this.eggSize.ordinal());
		compound.putBoolean("FromBroodEetle", this.fromBroodEetle);
	}

@Override
	protected void readAdditionalSaveData(CompoundTag compound) {
		this.fallTime = compound.getInt("FallTime");
		this.eggSize = EggSize.getById(Math.min(2, compound.getInt("EggSize")));
		this.fromBroodEetle = compound.getBoolean("FromBroodEetle");
	}

@Override
	public void tick() {
		super.tick();

		if (!this.level().isClientSide && this.isAlive()) {
			int age = this.growingAge;
			if (age < 0) {
				this.updateAge(++age);
			} else if (age > 0) {
				this.updateAge(--age);
			}
			if (!this.isBaby()) {
				if (this.idleDelay > 0) this.idleDelay--;
				if (this.despawnTimer > 0) {
					int newTime = --this.despawnTimer;
					if (newTime == 0) {
						this.level().broadcastEntityEvent(this, (byte) 20);
						this.discard();
					} else if (newTime <= 100 && newTime % 10 == 0) {
						LivingEntity attackTarget = this.getTarget();
						if (attackTarget != null && attackTarget.isAlive() && this.distanceToSqr(attackTarget) <= 256.0F && this.hasLineOfSight(attackTarget)) {
							this.despawnTimer += 105 + this.random.nextInt(11);
						}
					}
				}
			}
		}
	}

public void applyDespawnTimer() {
		this.despawnTimer = this.random.nextInt(101) + 600;
	}
